-- zhCN $g/$G tokens must end with ';' or the client prints leftover glyphs.

UPDATE `quest_template_locale` SET `Details` = '你不会认为我生来就是秃子吧？事实并不是这样的，$g先生:女士;！诺莫瑞根的放射性泄露导致了我悲剧性的脱发。在那之前，我有着整个艾泽拉斯世界独一无二的侏儒式飞机头！$B$B<诺恩一边说一边挥舞着拳头>$B$B那些该死的穴居怪——他们都该死！！$B$B或许现在还不晚，$N。我们也许仍然可以挽回局势——我说的是这座城市！去跟卡拉诺斯的奥齐·电环谈谈吧，他和他伙伴拉兹正在想办法。' WHERE `ID` = 2927 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '谢谢你帮我找到项链，$C$G先生:小姐;……你可真好！我的小猫也感谢你——对吗，喵喵？' WHERE `ID` = 3741 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你好，$g亲爱的先生:尊贵的女士;！你有时间吗？$B$B我和我兄弟在暴风城开了个药店，而我现在正要在这一带找些大蜡烛，以便提取其中的蜡。你能帮助我吗？$B$B你可以在狗头人身上找到大蜡烛，我听说在艾尔文森林的矿洞一带有很多狗头人……在南边的法戈第矿洞和东边的玉石矿洞里都有不少。我推荐你去这两个矿洞里看看。' WHERE `ID` = 60 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '我希望你能帮我们一把，$c。在上一次穴居人袭击之后，我们的人手就明显不够了。$b$b我听说他们现在已经遍布我们的国土，看来寒脊山谷也不能避免。东南部的山区和湖畔已经到处都是穴居人的身影了。$b$b糟糕的事情还不仅仅是这些，几天前，他们袭击并占领了我们西边的营地！$b$b我们这儿有些人手不足，$g孩子:姑娘;，我们需要强大的军队帮助我们赶走这些家伙。' WHERE `ID` = 170 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '嗯，$g小子:姑娘;，我想也许你不会帮我这个忙的。今天从隧道那边来了一大堆信，我想我没时间把它们都给发出去了。$b$b这些信都是寄给塔林·锐眼的。沿着这条路向西走就能找到他，就在结冰的湖泊附近。$b$b你能帮我这个忙么？' WHERE `ID` = 233 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '这本书叙述了元素公主密斯莱尔和她被囚禁在阿拉希高地下面的故事。$B$B它还叙述了高地里的一处秘密的水晶岩层。这些被称为“密斯莱尔水晶碎片”的东西是囚禁大地公主的监狱的窗户。$B$B如果某个勇敢的人能找到密斯莱尔水晶碎片，那么$g他:她;就有可能和她交谈……' WHERE `ID` = 636 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你需要雅格因的笔记？一整本？当然……当然我会帮助你，我的$g兄弟:姐妹;。$B$B但你也得帮我。$B$B我需要三件威力强大的物品，把这些物品给我找来，笔记就是你的了。$B$B我不能把它们的名字说出来，不过我可以给你写下来。$B$B把这个单子上的东西找来，如果你能完成这个任务，那么你就有能力接到更重要的工作。' WHERE `ID` = 736 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你已经猎杀了贫瘠之地的猛兽，在这个过程中你的精神力量也已经变得相当强大了。作为一个猎人，你应当时刻都作好准备，一个真正的猎手理应能在任何环境下追踪猎物。无论是山川还是沼泽都无法阻止$g他:她;。$B$B甚至连海洋都不能。$B$B去找到我的妹妹玛伦，她正在海岸边猎杀一种大型水兽，你可以从她那里学习更高深的狩猎之道。$B$B不过你找她的时候要当心，因为贫瘠之地的海岸一带是现在是被人类控制着的。' WHERE `ID` = 874 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你好，我的$g兄弟:姐妹;！你是来净化这里的水并展示从伊斯伦那里学到的东西的吗？$B$B我刚刚打败了堕落的水灵，正准备把护腕和馀下的水放在火盆上。$B$B那是什么？啊……只要有什么地方出了问题，提夫总能洞察一切。如果你想再次见到纯洁的水灵，提夫应该能帮你。$B$B从伊斯伦那里拿一瓶水之灵契来证明你已准备就绪，然后接下来的事情就交给我吧。' WHERE `ID` = 1103 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '太好了，总算碰到一个不是要来吃了我的人了！$B$B我正愁没人来帮我对付这儿的怪物哪，$g兄弟:小姐;，你看来就挺合适。$B$B那个叫摩根·斯特恩的厨子在研究一套新食谱，他让我来这儿采集一点睡菜叶。那家伙可能觉得睡菜叶挺好吃吧。$B$B就在我找睡菜的时候……我发现我被包围了！你能帮我从这儿逃出去吗？哦，对了，顺便在我找睡菜的时候替我断后。' WHERE `ID` = 1222 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '太好了，总算碰到一个不是要来吃了我的人了！$B$B我正愁没人来帮我对付这儿的怪物哪，$g兄弟:小姐;，你看来就挺合适。$B$B棘齿城一个叫麦伯克·米希瑞克斯的地精需要弄些睡菜叶……或是别的什么东西来做药剂，说实话我不在乎他做什么，反正他给的报酬不错，而我又正巧熟悉这个沼泽，所以我就来了。$B$B倒霉的是还没找到睡菜，我就被包围了！你能帮我从这儿逃出去吗？哦，对了，顺便在我找睡菜的时候替我断后。' WHERE `ID` = 1270 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '很抱歉，$g先生:夫人;。德拉维主教要我征召一些冒险者以帮助他解决一件棘手的事情。$B$B如果你能尽快而且悄悄地去一趟暴风要塞与他谈一谈的话，我想他将会非常感谢你的帮助。我得再申明一次，口风请紧一些，这件事情很重要。' WHERE `ID` = 1274 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '那么说你这个$g毛头小子:小姑娘;来这里就是给探险者协会里的某个老头子跑腿的吗？$b$b那你听好了，$c。我根本不知道他说的那个曾经在艾泽拉斯到处飞的老家伙是谁。你跑来问我这些，难道我脸上写着“狮鹫管理员沙拉克·鹰斧”这几个字吗？嗯？$b$b要是你想飞那么一次两次的，干嘛不去找个正儿八经的狮鹫饲养员呢？你要是还在这里继续闲晃的话，那我就真的要给你找点什么活去做做了。$b$b快走快走。' WHERE `ID` = 1450 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '卡利姆多之风正急切地想要见你，而你应该已经成为了我们最强大的$g兄弟:姐妹;之一。我很荣幸能够看到你的光辉未来。$B$B风元素是一种非常难以控制的元素，但是我相信以你的能力可以克服挡在你面前的一切困难。$B$B到贫瘠之地的最南端，然后从那里走到千针石林。你可以在千针石林的东部找到普拉特·白云，她可以教你更多的东西。' WHERE `ID` = 1532 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '啊！你吓了我一跳，$G先生:小姐;！你没看到我在思考吗？$B$B那是什么？乔丹的矿石…送去铁炉堡的……啊，这样啊，我知道你说的是什么了。那群莫格罗什食人魔抢走了我朋友的矿石，商队从这里转至湿地的路上遭到了埋伏。唯一从袭击中逃出的守卫也在前几天死掉了——医师没能及时赶到。$B$B你想找到那些矿石，就往东北方向去，在洛克湖的另一边。矿石一定就在那里的某个地方。' WHERE `ID` = 1655 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '很高兴再见到你，$N。我很荣幸能够称呼你为$g兄弟:姐妹;——你的奉献和无私对我们而言是一种恩赐。$B$B现在我要对你进行嘉奖了，但是你要知道，虽然这次我把它免费送给你，但是将来，如果时间允许的话，这将成为所有圣骑士都要接受的挑战。$B$B等一会再来与我交谈，我就将给你一份很棒的礼物。' WHERE `ID` = 1661 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '我今天就把这些拿给孩子们。你要多加小心，好心的$n。城里已经很难看到像你这样乐于助人的$G绅士:女士;了，不过你已经证明了圣骑士决不会拒绝帮助那些陷入困境的人。$B$B请多保重。' WHERE `ID` = 1780 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '徽章？哦，没什么，你应付不了的。看你的样子，我敢说马迪亚斯·肖尔一定会把你当成送奶酪的$g男孩:女孩;而不是个真正的盗贼。不管怎样，我被指派了一个任务，而且我曾保证要完成这个任务。$B$B对了，说到这个，你去把这个包裹带给马迪亚斯吧，他可能会交代你去做些事情。$B$B快去吧。' WHERE `ID` = 2205 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你好，我的$G兄弟:姐妹;。我们这里最有影响力的圣骑士——达索瑞恩·拉尔最近谈起过你。我听他说过你应该去找他接受试炼了……我也从他那里听说过你的出色表现。$B$B如果我是你，而且我有时间的话，我就会去暴风城和他聊聊的。我很肯定他会待在光明大教堂里——他一般都待在那里。' WHERE `ID` = 2998 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '噢，你好，$N。很高兴再次见到你。去达纳苏斯的旅途怎么样？$B$B你不在的这段时间里，我们取得了相当大的进展，你会为此感到高兴的。我们甚至保存了一整巢的蛋。不幸的是，我们找到这些蛋的母亲的时候，它已经死掉了。$B$B呃，你要取一只作为宠物吗？它们很快就要孵化了，所以它们会需要一个好$G父亲:母亲;的。你认为呢？$B$B如果你真的感兴趣的话，请带上一颗蛋，到闪光平原的赛车场去找奎恩丁。他会告诉你更多细节的。' WHERE `ID` = 3841 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '啊，很好，你来了。我派了一个$g魅魔:地狱火;跟着你，以便引起你的注意，但看起来你在它找到你之前就来到这里了。没关系。$B$B最近大家都知道你的力量在日渐增长，而且大家对此议论纷纷——这对你来说很好，但有可能对其它人来说就不是什么好消息了。这些都是鸡毛蒜皮的事情。重要的是，我觉得你已经证明了自己有资格得到……呵呵……某种祝福。$B$B在贫瘠之地的棘齿城中有一个名叫斯坦哈德的人，我相信你以前见过他的。' WHERE `ID` = 4487 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '仔细听着，海狗……藏宝海湾是让我们血帆海盗处处受制的根本原因。如果你杀死舰队指挥官卡拉·海角，我们就永远不会再遇到藏宝海湾的战舰了。如果你杀死大财主里维加兹，我们就永远不用被他们的法律捆住手脚了。$B$B如果你想要成为一个有荣誉感的舰队司令——没错，舰队司令，那么就按照我说的，去杀了他们两个。现在去吧，$g小伙子:姑娘;，当你完成了任务之后就回到我这儿来。' WHERE `ID` = 4621 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '小$G伙子:姑娘;，过来一下！我被一群嗜血如命的枭兽追赶，从我那个在冬泉谷南部的营帐里逃到了这儿！我觉得这可能是我离枭兽要保护的某种东西太近的缘故。$B$B我刚刚设法安全脱身，但是跟我一起的那个同伴可就没这么幸运了……你愿意到我的营地里去一趟吗？我真的需要那些补给物资，另外我还想取回昨天在挖掘场发现的护符。' WHERE `ID` = 4861 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你可以在永望镇找到玛雷弗斯·暗锤，$c。告诉他“芬克一切都好”，还有衣服很不错。$B$B然后给他这个。$B$B<芬克给了你一块光鲜的肉。>$B$B这是我“度假”时从比斯巨兽的内脏里摘出来的。$B$B我敢打赌，玛雷弗斯对看到这个东西的时候会大吃一惊的！$B$B哦，我猜你不知道永望镇在哪里，是吗？到冬泉谷去，$g小伙子:女士;！' WHERE `ID` = 5047 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你好，$g小伙子:小姑娘;。很高兴看到你长途跋涉来到如此遥远的地方。我并不是想要冒犯你，但是你们的许多族人对这里的严寒都不太习惯，很高兴你可以适应这里。$B$B不久之前，你们的一个女祭司来找过你——她说要你去达纳苏斯的月神殿找女祭司阿兰希雅，还说事情很紧急，所以你最好马上回去。' WHERE `ID` = 5630 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你好，$g小伙子:小姑娘;。很高兴在这里见到你。愿你和你的族人一切安好。$B$B当你在我们的土地上旅行的时候，你们那边的一位祭司来找过你。她说你必须尽快回到月神殿去，很遗憾，我无法告诉你更多的内容，但是听起来挺重要的。当你回到神殿里之后，就赶快去找女祭司阿兰希雅。' WHERE `ID` = 5633 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '$g小伙子:小姑娘;，不要虚度光阴，你该回一趟达纳苏斯了。女祭司阿兰希雅派人捎信来通知你返回家园进行试炼。他们似乎认为你已准备好接受新的试炼了，就像那些信仰圣光的人也要接受试炼一样。阿兰希雅说她正在月神殿等你，祝你好运。' WHERE `ID` = 5675 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '啊，我的$g兄弟:姐妹;，我真为你感到高兴！是时候让你回到达纳苏斯去和高阶女祭司阿兰希雅谈谈了。我的信使很肯定地说，你所属的教会要送新的袍子给你。$B$B你有空的时候就赶快回去一趟，待我向月神殿的姐妹们问好。$B$B愿艾露恩与你同在。' WHERE `ID` = 5683 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '爸爸让我给你这把钥匙，他说你可以用它打开房子后面的一只箱子。$B$B他还要让我谢谢你。你是不是帮过他？你有没有告诉他你帮我找到了我的洋娃娃？$B$B好吧，这里是钥匙。谢谢你，$N。谢谢你！你是个好心的$g先生:小姐;！' WHERE `ID` = 5942 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '嗨，这儿，$G小子:姑娘;！嗯，你想知道如何获得自己的宠物？$B$B好吧，我们这就开始吧。说到狩猎，没有什么比你的装备更重要了，但我们可以另选个时候来谈谈我的新式火枪。现在，我们说正经的，你肯定对此感兴趣：宠物！$B$B对你来说，学习的最好方法是挑选出一些生物来作为你的同伴，然后看看你喜欢哪些。那么，去找一头大型峭壁野猪，然后使用驯兽棒驯服它吧。' WHERE `ID` = 6064 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '$N，现在你已具备了驯服宠物的能力，但是你还必须掌握训练它的方法。$B$B到铁炉堡的军事大厅去跟我们最尊敬的驯兽师贝莉亚·雷岩谈谈吧，她将向你传授训练新宠物的方法，那么赶快出发吧，$G小子:小姑娘;！$B$B贝莉亚是个友好的驯兽师，你应该能和她相处得很融洽。祝你好运，$N。' WHERE `ID` = 6086 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '我是个大嗓门的矮人，我亲爱的$g小伙子:小姑娘;！我可不是为了钓鱼而生出来的！我的意思是，看看我！我是用石头刻出来的。$B$B我没有什么可保留的了——你已经把我知道的全都学会啦！$B$B你还不明白吗？啊，好吧。我在卡利姆多大陆有一个朋友，他也许可以帮你。他的名字叫纳特·帕格，是一个很友善的人。你可以在塞拉摩南边的岛上找到他。快出发吧！' WHERE `ID` = 6609 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '我可以从你手里的炒菜勺子看出你是干什么的。不幸的是，我什么也不能教你。$B$B不过我认识一个家伙，他是个地精，也许是卡利姆多大陆上最好的厨师。$B$B啊，也许这是个坏消息，$g小伙子:小姑娘;——你要跑一趟卡利姆多。到加基森去找迪尔格·奎克里弗，他会告诉你接下来该怎么做的。' WHERE `ID` = 6612 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '嗨，年轻的$g小伙子:姑娘;，你能帮冬天爷爷一个忙吗？$B$B似乎没有必要以第三人称来称呼自己，但是冬天爷爷在这儿一整天了，他也想要一份礼品呢。小姜饼和冰镇牛奶正合他的胃口。你能为冬天爷爷取些来吗？' WHERE `ID` = 6962 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '嗨，年轻的$g小伙子:姑娘;，你能帮冬天爷爷一个忙吗？$B$B似乎没有必要以第三人称来称呼自己，但是冬天爷爷在这儿一整天了，他也想要一份礼品呢。小姜饼和冰镇牛奶正合他的胃口。你能为冬天爷爷取些来吗？' WHERE `ID` = 7025 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '根据诺雷格·雷矛中尉的命令，所有雷矛部族的士兵都要杀掉$g他:她;在战场上看到的每一个兽人。$B$B带回兽人的獠牙来作为完成任务的证明。$B$B另外别忘了戴手套。' WHERE `ID` = 7402 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '这个伟大的时刻终于到来了，$N，接下来你就将获得你渴望已久的东西——你的战马。$B$B去和暴风城教堂区的格雷森·沙东布瑞克公爵谈谈吧。他将指引你完成必需的任务，令你获得一匹圣骑士最可信任的坐骑。$B$B我祝你在这次试炼中好运，为了圣光而战，我的$g兄弟:姐妹;！' WHERE `ID` = 7638 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '当我告诉白银之手骑士团的那帮家伙说我可以制造特殊的饲料来喂养灵魂马的时候，他们以为我疯了。每个人都认为我疯了！好吧，现在是算账的时候了！$B$B我可以制作你需要的东西，圣骑士$g先生:小姐;……所谓的勇士……不过你得为此破费一番。我需要只有银色黎明才会出售的可口的小点心——我要把它混合在饲料中。我还要求——没错，要求——我还要求你拿金币来弥补我所遭受的痛苦！$B$B向我展示你们吹嘘已久的牺牲精神吧，圣骑士。' WHERE `ID` = 7645 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '这个伟大的时刻终于到来了，$N，接下来你就将获得你渴望已久的东西——你的战马。$B$B去和暴风城教堂区的格雷森·沙东布瑞克公爵谈谈吧。他将指引你完成必需的任务，令你获得一匹圣骑士最可信任的坐骑。$B$B我祝你在这次试炼中好运，为了圣光而战，我的$g兄弟:姐妹;！' WHERE `ID` = 7670 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '我知道你为我收集了一些微缩残渣……如果你想要找一份全职工作的话，我想我一直都会需要这种残渣的。$B$B虽然我无法付出足够的报酬，但是我很乐意让我的地精朋友们都了解你这个伟大的$r$c，地精之友！$B$B相信我，$g先生:女士;，地精们的耳朵都是很灵验的……' WHERE `ID` = 7725 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '拇趾囊肿，$g小伙子:姑娘;。我的拇趾了出现囊肿。难道在这种混乱的情况下我只能砍下自己的脚来解除痛苦吗？这就是我请求你帮助我的原因。$B$B斯克兰格和博恩奈特让我杀掉这些家伙，这样他们就能派出探险队进入熔渣之池进行探索了，我说的就是那种叫做熏火龙还是什么玩艺的麻烦家伙。现在去杀了它们吧，在消灭熏火龙之前别回来找我。' WHERE `ID` = 7727 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你……你的装束真有趣。即使你心眼好，在陪一个生病的小孩子玩要糖果的恶作剧游戏，恐怕我还是得要求你做点什么！$B$B让我想想……你穿的衣服……看起来非常奇怪……你得炫耀自己的肌肉！是的，就是现在，炫耀你的肌肉吧，强壮的$g男:女;$c！$B$B你必须炫耀肌肉，这样我才会给你美味的暴风城杏仁糖。这可是万圣节的超美味糖果哦。' WHERE `ID` = 8356 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你……你的装束真有趣。即使你心眼好，在陪一个生病的小孩子玩要糖果的恶作剧游戏，恐怕我还是得要求你做点什么！$B$B让我想想……你穿的衣服……看起来非常奇怪……你得炫耀自己的肌肉！是的，就是现在，炫耀你的肌肉吧，强壮的$g男:女;$c！$B$B你必须炫耀肌肉，这样我才会给你美味的奥格瑞玛软糖。这可是万圣节的超美味糖果哦。' WHERE `ID` = 8359 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '我们并不是在独自与部落交战，$g小伙子:小姑娘;。$B$B如果我们可以取得胜利，那么我们就可以使用部落的资源来在其它的战场上对抗他们。反之，如果我们输掉了这场战争，那么在其它的战场上，部落将会占有优势。$B$B联盟需要更多你这种身经百战、意志坚定的老兵！$N，当你在所有战场上都与部落交战之后再回到我这里。' WHERE `ID` = 8371 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '你好，$g先生:小姐;，你不是传说中云游四海，无所不知的那种冒险者吗？最近的事情你都不知道？联盟正在准备对安其拉发动战争，我们需要大量的铁锭，越多越好。把它们带给我，每20块一组。我们会在功劳薄上为你记上一笔，怎么样，$c？' WHERE `ID` = 8494 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '我们系列历代都是着名的剥皮匠，$c。这就是联盟要求我们为了安其拉之战而收集轻皮的原因。我在这里的工作是确保皮革经过正确的处理，准备投入使用。但是我们需要你的帮助。$B$B因为我不得不留在这里，所以我需要你去帮忙收集皮革，然后把它们交给我。你觉得怎么样，$g小伙子:小姑娘;，你会帮我吗？' WHERE `ID` = 8511 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '真是钓鱼的好天气，你不这么认为吗，$g小伙子:姑娘;？这天气真好，我正好需要很多的鱼。部落让我负责收集大量的斑点黄尾鱼。这是为了即将开始的安其拉之战做准备。我告诉他们我会尽力而为的，所以我现在需要一些帮助。你可以帮帮我吗，$c？' WHERE `ID` = 8613 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '到时光之穴去吧，$N$g大人:女士;。阿纳克洛斯还在等你回去呢。把克苏恩之眼交给他，我相信他一定会很乐意在自己的收藏品中增加这么一件东西。' WHERE `ID` = 8802 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '<蒙托尔神父在你面前做了一个奇怪的手势。>$B$B幸运的$G小伙子:姑娘;，你找到那些阵亡士兵的护甲了吗？这些可怜的英雄在那场战争中咽下了最后一口气，还被天灾士兵脱去了所有护甲，连死亡的尊严都没能保住。$B$B把被玷污的护甲部件和净化所需的材料给我带来，你就会了解信仰的含义。' WHERE `ID` = 9111 AND `locale` = 'zhCN';
