UPDATE `quest_template_locale` SET `Details` = '我们和你一起渡过了一段最美好的时光$N。真希望你会是我们的$g爸爸:妈妈;。但你现在必须带我回达拉然的孤儿院里。$B$B也许你什么时候能再来看我们？我们喜欢去看冬鳞小鱼人和红龙女王。绝不会有人相信，我们竟然见到了造物主！$B$B我们会想念你的，$N。一定要给我们写信，我们也会给你写信的，好吗？' WHERE `ID` = 13959 AND `locale` = 'zhCN';
UPDATE `quest_template_locale` SET `Details` = '$g小伙子:姑娘;，在多条战联机同时进行战争的关键在于我们不能让军力过于分布，否则我们就会面临全面溃败的风险。$B$B每一天，我们都要对关键的军力布置进行调整。今天我们必须派遣援军的地方是阿拉希盆地。$B$B赶快到那里去，并带着胜利的消息回来见我，$N决不能允许那些部落的恶徒占据那里本应属于我们的资源！' WHERE `ID` = 14178 AND `locale` = 'zhCN';
