UPDATE `quest_template_locale` SET `Objectives` = '给道克·米希匹克斯带去一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。伊提斯综合症可不会不治而愈，年轻的$g先生:小姐;。' WHERE `ID` = 2609 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '我的表！太感谢你啦，善良的$g先生:女士;！$B$B虽然我们只是一群失去了土地的穷苦农民，但仍请你收下这份酬劳，以表达我们对你的感谢。' WHERE `ID` = 64 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '$N，你的英雄壮举将长存于我们的心中。人民军将会对你为西部荒野人民所做的一切感激不尽。范克里夫一死，迪菲亚兄弟会的命运也开始走向灭亡。希望在不久之后的某一天，和平会重新降临到这片美丽的土地上。$B$B我向你致敬，$g先生:女士;！' WHERE `ID` = 166 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '啧啧！我的名字叫葛兰斯，我想你是来照看我的吧？你是一个冒险者，就像我爸爸妈妈一样。我很高兴能遇到你。$B$B我希望我们之间能相处融洽。我有些事情想要做，而孤儿院院长说你在这个星期里会像大$G哥哥:姐姐;一样照顾我。我真是太高兴了。' WHERE `ID` = 172 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '干得漂亮，$g哥们:小姐;！' WHERE `ID` = 194 AND `locale` = 'zhCN';
