UPDATE `quest_offer_reward_locale` SET `RewardText` = '你猎了几只乌鸦呢，$G小伙子:小姑娘;？$B$B好狗儿，好狗儿！$B$B喔，这些猎犬让我想起来我在提瑞斯法饲养纯种犬的日子……那真是一段美好时光！' WHERE `ID` = 11227 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '<上尉松了一口气。>$B$B很好，这样减轻了我们的一些压力。$B$B$N，你又一次证明了你对西部卫戍要塞和联盟的价值。从财宝库中挑选一些吧，$g小伙子:小姑娘;！这是我们起码能做的！' WHERE `ID` = 11236 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '哇喔，那个号角真是冷啊！$B$B你再一次的拯救了西部卫戍要塞免于毁灭。你真是个令人感到好奇的$g男人:女人;，$N。你这样的人要是再多几个就好了。$B$B哎呀，这一定要受到奖赏的。你喜欢哪一样啊？' WHERE `ID` = 11238 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '标记得好，$g先生:小姐;！不过我得记得请后方要塞的火炮手喝酒啊。' WHERE `ID` = 11245 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '嗯，$g先生:女士;，我得说你做那项工作的时候有点太过投入了。$B$B<军士小心翼翼地看着你。>$B$B总之，如果你不介意，我要拿回我的弯刀了。它虽然有点钝了，不过我也不想你意外滑跤然后把我也给砍了。' WHERE `ID` = 11246 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '非常好，$g先生:小姐;。没有你的帮助，事情也完成不了。$B$B我确信上尉听到我报告我们在这的所做所为一定会感到很满意。' WHERE `ID` = 11247 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '很荣幸遇见你，$g先生:女士;！我期盼与你一起工作。$B$B说到这个，我们有一堆事要完成。' WHERE `ID` = 11248 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '没错，$g男孩:女孩;，那是不祥的东西，你显然做了对的选择。$B$B谢谢你把这个卷轴带来给我。我非常想要研究一下这东西的含意。如果要我大胆做出猜测，我会说这些维库人有可以超越死亡的方法——至少那些都是有资格的人。$B$B由于你击败了斯克恩族长，你证明了他没有资格。圣光不知道如果你没有杀掉他，他会变成什么样子，还有他会对我们做什么恐怖的事。' WHERE `ID` = 11249 AND `locale` = 'zhCN';
