UPDATE `quest_offer_reward_locale` SET `RewardText` = '你真是个$g英雄:女英雄;，$N。我相信我的顾客应该可以找到办法来释放宝石中他们所爱的人。这真是一次杰出的工作，你的酬劳已经准备好了。$B$B明天再来找我，我还有别的任务要托付给你。' WHERE `ID` = 11374 AND `locale` = 'zhCN';
