UPDATE `quest_offer_reward_locale` SET `RewardText` = '$N，因为你，暮冬要塞得救了。一想到你这个$g男人:女人;这么快就扭转整个战局，大多数的人都难以置信。但胜利已经到手！你重拾了人民的信仰，并赢得了长官对你的尊敬。$B$B<哈尔弗对你行了一个军礼。>$B$B弗塔根公爵已经回到了安加萨，全军进攻天谴之门，并且要求你的加入！我没有比你更优秀的士兵能推荐了去胜任这项工作了，$N。' WHERE `ID` = 12473 AND `locale` = 'zhCN';
