UPDATE `quest_offer_reward_locale` SET `RewardText` = '嗯，好！$B$B你帮我省了不少麻烦啊$g孩子:女孩;。我很感激。我会记得在报告上提到你的。$B$B你现在可以走了，菲肯斯坦应该在西边不远处等着你。' WHERE `ID` = 12519 AND `locale` = 'zhCN';
