UPDATE `quest_offer_reward_locale` SET `RewardText` = '<赫米特听着你描述你所得知的事情。>$B$B应该是在那边，$g孩子:女孩;。没有任何死犀牛可以告诫赫米特·奈辛瓦里说他该去哪里，能猎捕些什么。我们会做给那堆烂骨头看看。' WHERE `ID` = 12544 AND `locale` = 'zhCN';
