UPDATE `quest_offer_reward_locale` SET `RewardText` = '记住这些话，死亡骑士：符文熔炉是一种天灾设备。它只存在于阿彻鲁斯、纳克萨玛斯、以及冰冠冰川的中心！你只能够在符文熔炉铭刻你的武器。$B$B记得时常回来把你所有的武器刻上符文。一个死亡骑士必须准备好面对所有胆敢反抗$g他:她;的东西！' WHERE `ID` = 12842 AND `locale` = 'zhCN';
