UPDATE `quest_offer_reward_locale` SET `RewardText` = '做得好，$G小子:小女孩;。没想到你这么快就结交了盟友。$B$B如果你过阵子回来，我想一定可以找到一只雷羽鹰愿意让你骑的……因为它们现在知道可以信任你了。' WHERE `ID` = 12867 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '哈！真是个波澜万丈的故事，$G小子:小女孩;……也许你体内流着一点霜脉矮人的血，嗯？你不是空口说白话，这就是我想听的。' WHERE `ID` = 12874 AND `locale` = 'zhCN';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '坏消息，$G小子:小女孩;。这些铁矮人似乎数量越来越多……整个山区都看的到他们的踪迹。我闻到战争来临的味道。$B$B谢谢你对付这些家伙……又替咱们争取了一点时间。' WHERE `ID` = 12876 AND `locale` = 'zhCN';
